// Shared schematic light envelope. No calibrated physical rendering is implied.
export function normalizeLightSphere(raw={}){
 const num=(v,d,a,b)=>v!==null&&v!==''&&Number.isFinite(Number(v))?Math.max(a,Math.min(b,Number(v))):d;
 return {enabled:raw.enabled===true,follow:raw.follow!==false,position:{x:num(raw.position?.x,0,-5,5),y:num(raw.position?.y,1,0,6),z:num(raw.position?.z,0,-5,5)},radius:num(raw.radius,1.25,.2,5),strength:num(raw.strength,65,0,100),softness:num(raw.softness,65,0,100),kelvin:num(raw.kelvin,5600,2000,10000),colorMode:raw.colorMode==='gel'?'gel':'temperature',color:/^#[0-9a-f]{6}$/i.test(raw.color||'')?raw.color:'#fff1dc',azimuth:num(raw.azimuth,-35,-180,180),elevation:num(raw.elevation,35,-85,85)};
}
export function sphereCenter(plan,worldJoints){
 const s=normalizeLightSphere(plan.lightSphere);if(!s.follow)return {...s.position};const points=(plan.figures||[]).filter(f=>f.visible).flatMap(f=>Object.values(worldJoints(f)));if(!points.length)return {...plan.subject};return Object.fromEntries(['x','y','z'].map(k=>[k,(Math.min(...points.map(p=>p[k]))+Math.max(...points.map(p=>p[k])))/2]));
}
export function recommendedSphere(plan,worldJoints){const s=normalizeLightSphere({...plan.lightSphere,enabled:true,follow:true}),center=sphereCenter({...plan,lightSphere:s},worldJoints),points=(plan.figures||[]).filter(f=>f.visible).flatMap(f=>Object.values(worldJoints(f)));s.position=center;s.radius=Math.min(5,Math.max(.5,...points.map(p=>Math.hypot(p.x-center.x,p.y-center.y,p.z-center.z)+.25)));return s;}
export function sphereDirection(raw){const s=normalizeLightSphere(raw),a=s.azimuth*Math.PI/180,e=s.elevation*Math.PI/180;return {x:Math.sin(a)*Math.cos(e),y:Math.sin(e),z:-Math.cos(a)*Math.cos(e)};}
export function spherePlaneMove(position,basis,dx,dy,scale){const determinant=basis.right.x*basis.up.y-basis.right.y*basis.up.x;if(!Number.isFinite(scale)||scale<=0||Math.abs(determinant)<.08)return null;const sx=dx/scale,sy=-dy/scale;return {x:Math.max(-5,Math.min(5,position.x+(sx*basis.up.y-basis.right.y*sy)/determinant)),y:Math.max(0,Math.min(6,position.y+(basis.right.x*sy-sx*basis.up.x)/determinant)),z:position.z};}
export function sphereText(plan,worldJoints){const s=normalizeLightSphere(plan.lightSphere);if(!s.enabled)return '';const c=sphereCenter(plan,worldJoints),n=v=>Number(v).toFixed(2);return ` Lighting envelope direction: an invisible spherical lighting guide centered at (${n(c.x)}, ${n(c.y)}, ${n(c.z)}) m, radius ${n(s.radius)} m, ${s.colorMode==='gel'?'tint '+s.color:s.kelvin+' K'}, descriptive strength ${n(s.strength)}/100, softness ${n(s.softness)}/100. Dominant light azimuth ${n(s.azimuth)} degrees from front (-Z), elevation ${n(s.elevation)} degrees; use soft surrounding fill according to softness. The sphere is a lighting guide, not an object to draw. Preserve the other light relationships. These settings describe intent rather than calibrated exposure.`;}
